function icon(string $name = 'bolt'): string {
    $paths = ['bolt'=>'m13 2-9 12h7l-1 8 10-12h-7l1-8Z','phone'=>'M8 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-4l-5-2-2 2a13 13 0 0 1-6-6l2-2-2-5Z','arrow'=>'M5 12h14m-6-6 6 6-6 6','pin'=>'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z','check'=>'m5 12 4 4L19 6','shield'=>'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Zm-5 10 3 3 7-7','plug'=>'M8 3v5m8-5v5M5 8h14v4a7 7 0 0 1-14 0V8Zm7 11v3','panel'=>'M4 3h16v18H4V3Zm4 4v4m4-4v4m4-4v4M8 15h8m-8 3h8'];
    return '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="' . ($paths[$name] ?? $paths['bolt']) . '"/></svg>';
}
function cta(array $c, string $label = 'Appeler un électricien', string $class = ''): void {
    $phone = phone_link($c);
    if ($phone) echo '<a class="button ' . e($class) . '" href="' . e($phone) . '">' . icon('phone') . e($label) . '</a>';
    else echo '<span class="button unavailable ' . e($class) . '" aria-disabled="true">' . icon('phone') . 'Téléphone à renseigner</span>';
}
function head(array $c, string $title, string $description, string $path, bool $indexable, array $schema = []): void {
    $indexable = $indexable && !local_mode();
    if (!$indexable) header('X-Robots-Tag: noindex, nofollow');
    $canonical = http_url($c['site_url'] ?? '') ? rtrim($c['site_url'], '/') . $path : '';
    ?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#172d35"><title><?= e($title) ?></title><meta name="description" content="<?= e($description) ?>"><meta name="robots" content="<?= $indexable ? 'index,follow' : 'noindex,nofollow' ?>"><?php if ($canonical): ?><link rel="canonical" href="<?= e($canonical) ?>"><?php endif ?><meta property="og:title" content="<?= e($title) ?>"><meta property="og:description" content="<?= e($description) ?>"><meta property="og:type" content="website"><meta property="og:locale" content="fr_FR"><link rel="stylesheet" href="/assets/site.css?v=1"><script src="/assets/site.js?v=1" defer></script><?php if ($schema && $indexable): ?><script type="application/ld+json"><?= json_encode($schema, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?></script><?php endif ?></head><body><a class="skip" href="#main">Aller au contenu</a>
    <?php if (preview_allowed()): ?><div class="preview">PRÉVISUALISATION · Coordonnées et zones à valider avant publication <a href="/admin/">Administration ↗</a></div><?php endif ?>
    <header class="header"><a class="brand" href="/" aria-label="Accueil"><?php if (asset_path($c['logo'] ?? '')): ?><img src="<?= e($c['logo']) ?>" alt="" width="42" height="42"><?php else: ?><span class="brand-icon"><?= icon() ?></span><?php endif ?><span><?= e($c['name'] ?: 'Votre électricien') ?><small>NOGENT & ALENTOURS</small></span></a><nav class="nav" aria-label="Navigation principale"><a href="/#services">Nos prestations</a><a href="/electricien/">Nos villes</a><a href="/conseils/">Conseils</a></nav><div class="header-call"><?php if (phone_link($c)): ?><a href="<?= e(phone_link($c)) ?>"><?= icon('phone') ?><span><?= e($c['phone_display'] ?: $c['phone']) ?></span></a><?php else: ?><a href="#contact">Nous contacter <?= icon('arrow') ?></a><?php endif ?></div></header>
    <?php
}
