function local_schema(array $p, array $c): array {
    $base = rtrim($c['site_url'], '/');
    $provider = ['@type'=>'Electrician','@id'=>$base.'/#entreprise','name'=>$c['name'],'url'=>$base.'/','telephone'=>$c['phone'],'areaServed'=>array_map(fn($x)=>['@type'=>'City','name'=>$x['city']],array_values(array_filter(pages('city'), fn($x)=>live($x,$c))))];
    if (!empty($c['address_verified']) && is_array($c['address'])) $provider['address'] = array_merge($c['address'], ['@type'=>'PostalAddress']);
    return ['@context'=>'https://schema.org','@graph'=>[$provider, ['@type'=>'Service','@id'=>$base.page_url($p).'#service','name'=>'Dépannage électrique à '.$p['city'],'provider'=>['@id'=>$base.'/#entreprise'],'areaServed'=>['@type'=>'City','name'=>$p['city']],'url'=>$base.page_url($p)], ['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Accueil','item'=>$base.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Villes','item'=>$base.'/electricien/'],['@type'=>'ListItem','position'=>3,'name'=>$p['city'],'item'=>$base.page_url($p)]]]]];
}
function city_page(array $p, array $c): void {
    head($c,$p['meta_title'],$p['description'],page_url($p),live($p,$c),live($p,$c)?local_schema($p,$c):[]); ?>
