    <section class="local-layout wrap" id="details"><div class="editorial"><span class="eyebrow">VOTRE INSTALLATION, VOTRE QUARTIER</span><?php foreach ($p['sections'] as $i=>$s): ?><section class="prose-section"><h2><?= e($s['title']) ?></h2><?php foreach ($s['paragraphs'] as $para): ?><p><?= e($para) ?></p><?php endforeach ?></section><?php if ($i===1): ?><div class="inline-cta"><span>Besoin de faire le point ?</span><?php cta($c, 'Parler de votre panne', 'compact') ?></div><?php endif ?><?php endforeach ?></div><aside class="local-aside"><div class="area-card"><span class="eyebrow"><?= icon('pin') ?> REPÈRES LOCAUX</span><h2><?= e($p['city']) ?><small><?= e($p['postal_code']) ?></small></h2><p><?= e($p['local_note']) ?></p><div class="districts"><?php foreach (($p['coverage_verified'] ? $p['verified_districts'] : $p['districts']) as $d): ?><span><?= e($d) ?></span><?php endforeach ?></div><p class="fine"><?= $p['coverage_verified'] ? 'Quartiers dont la desserte a été confirmée par l’entreprise. Précisez toujours votre adresse lors de l’appel.' : 'Repères géographiques vérifiés. La desserte par l’entreprise reste à confirmer avant publication.' ?></p></div><div class="safety-card"><span class="eyebrow">LE BON RÉFLEXE</span><h3>Une coupure dans toute la rue ?</h3><p>Consultez les incidents du réseau avant de demander un dépannage de votre installation.</p><a href="https://www.enedis.fr/panne-et-interruption" rel="noopener">Consulter Enedis ↗</a></div></aside></section>
    <?php process_section(); pricing_section($c); proof_section($p,$c); faq_section($p); ?>
