function process_section(): void { ?><section class="process"><div class="wrap"><span class="eyebrow">UNE INTERVENTION BIEN PRÉPARÉE</span><h2>Du premier appel<br>à la remise en service.</h2><div class="steps"><?php foreach ([['Échanger','Décrivez la panne, votre adresse et les circuits concernés. Faites confirmer la disponibilité.'],['Comprendre','Le diagnostic permet de préciser l’origine du défaut et les travaux nécessaires.'],['Décider','Demandez les conditions tarifaires et un devis détaillé avant de donner votre accord.'],['Vérifier','À l’issue des travaux convenus, faites expliquer les vérifications et les précautions utiles.']] as $i=>[$t,$d]): ?><div><span class="step-number">0<?= $i+1 ?></span><h3><?= e($t) ?></h3><p><?= e($d) ?></p></div><?php endforeach ?></div></div></section><?php }
function pricing_section(array $c): void { ?><section class="pricing wrap"><div><span class="eyebrow">LE PRIX, AVANT LES TRAVAUX</span><h2>Un dépannage.<br>Des conditions claires.</h2></div><div><?php if (!empty($c['pricing_verified'])): ?><p><?= nl2br(e($c['pricing_text'])) ?></p><?php else: ?><p>Aucun tarif n’est affiché tant que les conditions de l’entreprise ne sont pas validées. Demandez le coût du déplacement, de la main-d’œuvre, des pièces et les éventuelles majorations.</p><?php endif ?><p>Un devis détaillé permet de connaître le périmètre des travaux avant de vous engager.</p><a href="https://www.service-public.gouv.fr/particuliers/vosdroits/F38350">Comprendre le devis de dépannage ↗</a></div></section><?php }
function proof_section(array $p,array $c): void {
    $review=$p['review']??[]; $photo=$p['photo']??[];
    if (!empty($c['experience_verified'])) echo '<section class="wrap proof"><h2>Votre électricien</h2><p>'.e($c['experience_text']).'</p></section>';
    if (!empty($c['insurance_verified'])) echo '<section class="wrap proof"><h2>Assurance professionnelle</h2><p>'.e($c['insurance_text']).'</p></section>';
    foreach ($c['qualifications']??[] as $q) if (!empty($q['verified']) && http_url($q['source']??'')) echo '<p class="wrap"><a href="'.e($q['source']).'">'.e($q['label']).'</a></p>';
    if (!empty($review['verified']) && ($review['city']??'')===$p['city'] && http_url($review['source']??'')) echo '<section class="wrap proof"><h2>Un retour à '.e($p['city']).'</h2><blockquote>'.e($review['text']).'</blockquote><a href="'.e($review['source']).'">'.e($review['author']).' · Lire l’avis original ↗</a></section>';
    if (!empty($photo['verified']) && !empty($photo['permission']) && asset_path($photo['path']??'')) echo '<figure class="wrap proof"><img src="'.e($photo['path']).'" alt="'.e($photo['alt']).'" width="1200" height="800" loading="lazy"><figcaption>'.e($photo['caption']).'</figcaption></figure>';
}
function faq_section(array $p): void { ?><section class="faq wrap"><div><span class="eyebrow">VOS QUESTIONS, SIMPLEMENT</span><h2>L’essentiel à savoir<br>pour <?= e($p['city']) ?>.</h2></div><div><?php foreach ($p['faq'] as $q): ?><details><summary><?= e($q['question']) ?><span aria-hidden="true">+</span></summary><p><?= e($q['answer']) ?></p></details><?php endforeach ?></div></section><?php }
